    printf("[*] Sampling: k0 in full [0,2^20), k1,k2,k3 in [0, 2^15)\n");

    for (uint32_t k0 = 0; k0 < (1U << 20); k0++) {
        if ((k0 & 0xFFFF) == 0) {
            printf("[*] k0 progress: 0x%05x\n", k0);
            fflush(stdout);
        }

        for (uint32_t k1 = 0; k1 < (1U << 15); k1++) {
            for (uint32_t k2 = 0; k2 < (1U << 15); k2++) {
                for (uint32_t k3 = 0; k3 < (1U << 15); k3++) {
                    if (check_key(k0, k1, k2, k3)) {
                        printf("[+++] FOUND KEY: k0=%05x k1=%05x k2=%05x k3=%05x\n", 
                               k0, k1, k2, k3);

                        FILE *cf = fopen("/app/ciphertexts.txt", "r");
                        FILE *out = fopen("/app/plaintexts.txt", "w");
                        uint64_t ct;
                        while (fscanf(cf, "%lu", &ct) == 1) {
                            fprintf(out, "%lu\n", decrypt(ct));
                        }
                        fclose(cf);
                        fclose(out);
                        printf("[+] Plaintexts saved to /app/plaintexts.txt\n");
                        return 0;
                    }
                }
            }
        }
    }

    return 1;
}
EOF
gcc -O3 -march=native -o /tmp/fast_key_recovery /tmp/fast_key_recovery.c
